async function updateBattlecards() {
  console.log(`Actualizando ${battlecards.length} battlecards con guiones exactos...`)
  let errors = 0
  
  for (const card of battlecards) {
    const { error } = await supabase
      .from('battlecards')
      .upsert(card, { onConflict: 'id' })
    
    if (error) {
      console.error(`\n❌ Error battlecard ${card.id}:`, error.message)
      errors++
    } else {
      process.stdout.write(`✓${card.id} `)
    }
  }
  
  console.log(`\n\n${errors === 0 ? '✅' : '⚠️'} Completado. ${battlecards.length - errors} OK, ${errors} errores.`)
}

updateBattlecards()
